"""A very small evaluator for a subset of Forth.

Supports signed-integer arithmetic (``+``, ``-``, ``*``, ``/``), stack
manipulation (``dup``, ``drop``, ``swap``, ``over``) and user-defined
words introduced with the customary syntax ``: name definition ;``.
Words are case-insensitive.
"""

import re

_NUMBER_RE = re.compile(r"-?\d+", re.ASCII)


class StackUnderflowError(Exception):
    """Raised when an operation needs more items than the stack has."""


def _is_number(token):
    return _NUMBER_RE.fullmatch(token) is not None


def _underflow():
    raise StackUnderflowError("Insufficient number of items in stack")


def _add(stack, words):
    if len(stack) < 2:
        _underflow()
    b = stack.pop()
    a = stack.pop()
    stack.append(a + b)


def _sub(stack, words):
    if len(stack) < 2:
        _underflow()
    b = stack.pop()
    a = stack.pop()
    stack.append(a - b)


def _mul(stack, words):
    if len(stack) < 2:
        _underflow()
    b = stack.pop()
    a = stack.pop()
    stack.append(a * b)


def _div(stack, words):
    if len(stack) < 2:
        _underflow()
    b = stack.pop()
    a = stack.pop()
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    stack.append(a // b)


def _dup(stack, words):
    if not stack:
        _underflow()
    stack.append(stack[-1])


def _drop(stack, words):
    if not stack:
        _underflow()
    stack.pop()


def _swap(stack, words):
    if len(stack) < 2:
        _underflow()
    stack[-1], stack[-2] = stack[-2], stack[-1]


def _over(stack, words):
    if len(stack) < 2:
        _underflow()
    stack.append(stack[-2])


_BUILTINS = {
    "+": _add,
    "-": _sub,
    "*": _mul,
    "/": _div,
    "dup": _dup,
    "drop": _drop,
    "swap": _swap,
    "over": _over,
}


def _compile_body(tokens, words):
    """Compile the tokens of a word definition into an executable body.

    Numbers become integers.  References to words that are already defined
    are expanded at definition time: built-ins are kept by reference and
    user words are inlined (this is what lets a word capture the current
    meaning of another word).  Anything else is kept as a string to be
    resolved when the word is executed.
    """
    body = []
    for token in tokens:
        if _is_number(token):
            body.append(int(token))
        elif token in words:
            value = words[token]
            if callable(value):
                body.append(value)
            else:
                body.extend(value)
        else:
            body.append(token)
    return body


def _define(tokens, words):
    if len(tokens) < 3:
        raise ValueError("illegal operation")
    name, body_tokens = tokens[1], tokens[2:]
    if body_tokens and body_tokens[-1] == ";":
        body_tokens = body_tokens[:-1]
    if _is_number(name):
        raise ValueError("illegal operation")
    words[name] = _compile_body(body_tokens, words)


def _execute(tokens, stack, words):
    for token in tokens:
        if _is_number(token):
            stack.append(int(token))
        elif token in words:
            value = words[token]
            if callable(value):
                value(stack, words)
            else:
                _execute(value, stack, words)
        else:
            raise ValueError("undefined operation")


def evaluate(input_data):
    """Evaluate a list of Forth source lines and return the final stack."""
    stack = []
    words = dict(_BUILTINS)
    for line in input_data:
        tokens = [token.lower() for token in line.split()]
        if not tokens:
            continue
        if tokens[0] == ":":
            _define(tokens, words)
        else:
            _execute(tokens, stack, words)
    return stack

